          <p class="text-slate-600 text-sm">Save the template and run through the Quick Review Checklist before testing.</p>
        </div>
      </div>
    </div>
  </div>
</div>',
      title = 'Build the Template',
      lesson_number = 3,
      sort_order = 3,
      updated_at = NOW()
    WHERE id = v_lesson_id;
    
    RAISE NOTICE 'Updated lesson: Build the Template';
  END IF;

END $$;


-- Insert Quiz Questions for Lesson: Build the Template

DO $$
DECLARE
  v_module_id UUID;
  v_lesson_id UUID;
  v_quiz_id UUID;
BEGIN
  -- Get Module by week number
  SELECT id INTO v_module_id FROM public.training_modules WHERE week_number = 14 LIMIT 1;
  
  IF v_module_id IS NULL THEN
    RAISE NOTICE 'Module 14 not found';
    RETURN;
  END IF;

  -- Get the lesson ID
  SELECT id INTO v_lesson_id 
  FROM public.lessons 
  WHERE slug = 'build-the-template' AND module_id = v_module_id;
  
  IF v_lesson_id IS NULL THEN
    RAISE NOTICE 'Lesson build-the-template not found in module 14';
    RETURN;
  END IF;
  
  -- Delete existing quizzes to avoid duplicates
  DELETE FROM public.lesson_quizzes WHERE lesson_id = v_lesson_id;


  -- Question 1
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'Where are reusable templates created?', 
    '["Automation → Workflows","Payments → Documents and Contracts → Templates","Contacts → Documents","Settings → Templates"]'::jsonb,
    'Payments → Documents and Contracts → Templates',
    'Reusable templates are created in Payments → Documents and Contracts → Templates by selecting + New → Create New Template.', 
    1
  )
  RETURNING id INTO v_quiz_id;


  -- Question 2
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'What naming pattern makes templates easier to find?', 
    '["Date — Client Name — Version","Document Type — Service or Audience — Version","Version — Date — Document Type","Client Name — Date — Service"]'::jsonb,
    'Document Type — Service or Audience — Version',
    'Use the pattern: Document Type — Service or Audience — Version. Examples: Speaking Agreement — Keynote — 2026.', 
    2
  )
  RETURNING id INTO v_quiz_id;


  -- Question 3
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'Do changes to a template alter a document that has already been sent?', 
    '["Yes, all sent documents are automatically updated","No, sent documents are not changed by later template edits","Only if the document is in draft status","Only if the recipient has not yet opened it"]'::jsonb,
    'No, sent documents are not changed by later template edits',
    'Sent documents are not changed by later template edits. Each document is a snapshot created at the time of sending.', 
    3
  )
  RETURNING id INTO v_quiz_id;

END $$;
